/* Local research projects. Private work stays in IndexedDB until explicitly exported. */
(()=>{
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const id=()=>crypto.randomUUID();let dbPromise,projects=[],current=null,active='library',epoch=0;
 let mapView={z:1,x:0,y:0};const tabs=['library','reader','evidence','claims','synthesis','design','map','proposal','review'];
 function db(){return dbPromise||(dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('rei-research',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}))}
 async function store(mode,fn){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('projects',mode),r=fn(tx.objectStore('projects'));let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
 async function persist(){const project=current;if(!project)return;project.updated=new Date().toISOString();const snapshot=structuredClone(project);await store('readwrite',s=>s.put(snapshot));const status=document.querySelector('#research-status');if(status)status.textContent='Saved on this device'}
 function statusError(){toast('Could not save this change. Keep this page open and export a backup.');const s=document.querySelector('#research-status');if(s)s.textContent='Not saved — export a backup'}
 const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
 const doi=s=>String(s||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').replace(/^doi:\s*/i,'').toLowerCase();
 function file(name,text,type='application/json'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
 function shell(){return '<div class="container research-shell"><div role="status" class="research-loading">Opening your research studio…</div></div>'}
 const badge='<span class="local-badge">LOCAL WORKSPACE · NO ACCOUNT NEEDED</span>';
 const projectTemplates={blank:{label:'Blank project',question:'',design:null},literature:{label:'Literature review',question:'What does the existing research show, and where do findings differ?',design:{objective:'Synthesize the existing evidence',measure:'Themes, findings, and limitations',population:'Studies in the selected literature',sample:'Sources selected with stated inclusion criteria',collection:'Structured literature search and screening',analysis:'Thematic comparison across sources',ethics:'Respect source attribution and avoid misrepresenting findings',feasibility:'Define a realistic search scope and review schedule',rationale:'A transparent synthesis answers the question through the recorded evidence.'}},survey:{label:'Survey study',question:'How do participants experience or respond to this topic?',design:{objective:'Describe participant responses',measure:'Survey items and response patterns',population:'The target participant group',sample:'A justified recruitment and sampling plan',collection:'Consent-based questionnaire collection',analysis:'Descriptive and comparative analysis of responses',ethics:'Consent, privacy, and safe handling of participant data',feasibility:'Recruitment access, timeline, and available tools',rationale:'The measures and analysis connect participant responses to the research question.'}},interview:{label:'Interview study',question:'How do people describe their experience of this topic?',design:{objective:'Understand participant perspectives',measure:'Interview themes and meanings',population:'People with relevant lived experience',sample:'A justified selection of interview participants',collection:'Consent-based semi-structured interviews',analysis:'Thematic coding with a reflexive audit trail',ethics:'Consent, confidentiality, privacy, and participant risk',feasibility:'Access, interview time, transcription, and researcher capacity',rationale:'Open-ended accounts help explain how participants experience the question.'}},evaluation:{label:'Experiment or evaluation',question:'What changes after this intervention, practice, or condition?',design:{objective:'Evaluate a change or outcome',measure:'Predefined outcome measures and comparison',population:'The people or materials affected by the intervention',sample:'A justified comparison or selection plan',collection:'Consistent measurement before and after the intervention',analysis:'Comparison of outcomes with uncertainty and limitations',ethics:'Consent, safety, privacy, and equitable participation',feasibility:'Time, access, equipment, and implementation constraints',rationale:'The measurement and comparison plan links the intervention to the outcome.'}}};
 function nav(){return `<a class="text-link" href="#research">← All projects</a><nav class="research-tabs" aria-label="Research project">${tabs.map(t=>`<a href="#research/${e(current.id)}/${t}" ${active===t?'aria-current="page"':''}>${({library:'Library',map:'Literature map',evidence:'Evidence table',proposal:'Proposal studio',reader:'Reader',claims:'Claims',synthesis:'Synthesis matrix',design:'Research design',review:'Review & history'})[t]}</a>`).join('')}</nav>`}
 function field(label,name,value='',type='text',required=false){return `<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} maxlength="${name==='title'?300:2000}"></label>`}
 function area(label,name,value='',rows=4){return `<label>${label}<textarea name="${name}" rows="${rows}" maxlength="100000">${e(value)}</textarea></label>`}
 function formProject(){return `<form id="project-create" class="research-form"><h2>Start with a question.</h2><p>You can refine it as your research develops. A starter template can add a first method plan without locking your choices.</p>${field('Project title','title','', 'text',true)}${area('Working research question','question','',3)}<label>Starter template<select name="template">${Object.entries(projectTemplates).map(([key,t])=>`<option value="${key}">${t.label}</option>`).join('')}</select></label><button class="button primary">Create project</button></form>`}
 function projectList(){return `<div class="research-heading"><div class="research-sculpture sculpture" data-sculpture="38" aria-hidden="true"><img class="sculpture-fallback" src="particle-fallback.svg" alt=""><canvas></canvas></div>${badge}<h1>Your next discovery<br><span>starts with a question.</span></h1><p>A dedicated space for the sources, evidence, and thinking behind your proposal.</p></div><div class="research-project-layout"><section><div class="research-section-label"><h2>Your projects</h2><span>${projects.length} / 5 projects</span></div>${projects.length?projects.map(p=>`<a class="project-row" href="#research/${e(p.id)}/library"><div><span class="eyebrow">${p.papers.length} SOURCES · ${p.evidence.length} EVIDENCE NOTES</span><h3>${e(p.title)}</h3><p>${e(p.question||'Add evidence and refine your research direction.')}</p></div><span aria-hidden="true">↗</span></a>`).join(''):'<div class="research-empty"><span class="empty-orbit" aria-hidden="true">◎</span><h3>Make room for your research.</h3><p>Create a project, add your first source, then connect evidence to your proposal.</p></div>'}<div class="research-backup"><label class="button secondary">Restore project backup<input id="research-restore" type="file" accept=".json,application/json" aria-label="Restore project backup"></label><p>Restore a REI project JSON file. Existing projects are never overwritten.</p></div></section>${projects.length<5?formProject():'<div class="research-empty"><h2>Project limit reached</h2><p>This local beta supports five projects. Your existing work and exports remain available.</p></div>'}</div>`}
 function paperForm(){return `<details class="research-add"><summary>Add a paper manually <span>+</span></summary><form id="paper-add" class="research-form"><p>Record the source accurately, or import references below. Live discovery services are not connected.</p>${field('Paper title','title','','text',true)}<div class="research-form-grid">${field('Authors','authors')}${field('Publication year','year','','number')}${field('DOI (optional)','doi')}${field('Source URL (optional)','url','','url')}${field('Publication / journal','venue')}${field('Collection','collection','Reading list')}</div>${area('Abstract or description','abstract','',3)}<button class="button primary">Save paper</button></form></details>`}
 function library(){return `<div class="research-section-label"><div><h2>A library with direction.</h2><p>Keep useful sources together. Record what you have read and why it matters.</p></div><span>${current.papers.length} / 200 papers</span></div><div class="research-notice"><strong>Your sources stay with you.</strong> Add papers manually or import CSV, RIS, and BibTeX below. Live discovery is not connected.</div>${paperForm()}<div class="research-filter"><label>Find a saved paper<input id="paper-filter" type="search" placeholder="Title, author, or collection"></label></div><div id="paper-list">${current.papers.length?current.papers.map(p=>`<article class="paper-record" data-search="${e((p.title+' '+p.authors+' '+p.collection).toLowerCase())}"><div class="paper-number">${String(current.papers.indexOf(p)+1).padStart(2,'0')}</div><div><span class="eyebrow">${e(p.collection)} · ${e(p.year||'YEAR NOT RECORDED')}</span><h3>${e(p.title)}</h3><p>${e(p.authors||'Authors not recorded')} ${p.venue?'· '+e(p.venue):''}</p>${p.abstract?`<details><summary>Read description</summary><p>${e(p.abstract)}</p></details>`:''}<label class="paper-note">Your reading notes<textarea rows="3" data-paper-note="${e(p.id)}" maxlength="100000">${e(p.notes||'')}</textarea></label><div class="paper-actions">${safeUrl(p.url|| (p.doi?'https://doi.org/'+p.doi:''))?`<a class="text-link" href="${e(safeUrl(p.url||(p.doi?'https://doi.org/'+p.doi:'')))}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}<label>Reading status<select data-reading="${e(p.id)}">${['To read','Reading','Read'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="text-button" data-paper-verify="${e(p.id)}">Verify DOI</button><button class="text-button" data-paper-edit="${e(p.id)}">Edit details</button><button class="text-button" data-paper-remove="${e(p.id)}">Remove</button></div></div></article>`).join(''):'<div class="research-empty"><h3>Your first source belongs here.</h3><p>Open “Add a paper manually” above to start your collection.</p></div>'}</div><p id="paper-no-results" hidden>No saved papers match your search.</p>`}
 function options(){return current.papers.map(p=>`<option value="${e(p.id)}">${e(p.title)}</option>`).join('')}
 function evidence(){return `<div class="research-section-label"><div><h2>From sources to understanding.</h2><p>Compare what each study did, found, and left unanswered.</p></div></div>${current.papers.length?`<details class="research-add"><summary>Add evidence note <span>+</span></summary><form id="evidence-add" class="research-form"><label>Source paper<select name="paperId">${options()}</select></label>${field('Research question / purpose','purpose')}<div class="research-form-grid">${area('Method','method','',3)}${area('Population / context','context','',3)}</div>${area('Main findings','findings')}${area('Limitations','limitations','',3)}${area('Relevance to your project','relevance','',3)}<div class="research-form-grid">${field('Study type','studyType')}${field('Sample or material','sample')}</div>${area('Transferability / boundary','transferability','',3)}${area('Conflicts or funding to consider','conflicts','',3)}${field('Your confidence in this interpretation','confidence')}${field('Page or section locator (optional)','locator')}<button class="button primary">Save evidence note</button></form></details>`:'<div class="research-empty"><h3>Start with a source.</h3><p>Add a paper to your library before recording evidence.</p><a class="button primary" href="#research/${e(current.id)}/library">Open library</a></div>'}${current.evidence.length?`<div class="evidence-table-wrap" tabindex="0" role="region" aria-label="Evidence comparison table"><table class="evidence-table"><caption>Compare your recorded evidence</caption><thead><tr><th scope="col">Source</th><th scope="col">Method</th><th scope="col">Findings</th><th scope="col">Limitations</th></tr></thead><tbody>${current.evidence.map(n=>`<tr><th scope="row">${e(current.papers.find(p=>p.id===n.paperId)?.title||'Source removed')}</th><td>${e(n.method||'Not recorded')}</td><td>${e(n.findings||'Not recorded')}</td><td>${e(n.limitations||'Not recorded')}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="evidence-records">${current.evidence.map(n=>{const p=current.papers.find(p=>p.id===n.paperId);return `<article class="evidence-record"><span class="eyebrow">STUDENT-AUTHORED EVIDENCE</span><h3>${e(p?.title||'Source removed')}</h3><dl>${['quote','purpose','method','context','findings','limitations','relevance','studyType','sample','transferability','conflicts','confidence','locator'].filter(k=>n[k]).map(k=>`<div><dt>${k==='locator'?'Source location':k==='quote'?'Exact passage':k}</dt><dd>${e(n[k])}</dd></div>`).join('')}</dl><div class="actions"><button class="button secondary" data-insert-evidence="${e(n.id)}">Use in proposal ↗</button><button class="text-button" data-evidence-edit="${e(n.id)}">Edit note</button><button class="text-button" data-evidence-remove="${e(n.id)}">Remove note</button></div></article>`}).join('')}</div>${current.evidence.length?'<button class="button secondary" data-research-export="csv">Export evidence CSV</button>':''}`}
 function map(){const ps=current.papers.slice(0,100);const pos=new Map(ps.map((p,i)=>[p.id,{x:400+Math.cos(i/Math.max(1,ps.length)*Math.PI*2)*Math.min(260,70+ps.length*12),y:260+Math.sin(i/Math.max(1,ps.length)*Math.PI*2)*Math.min(190,50+ps.length*10)}]));return `${window.REIWorkbench.graph()}<div class="research-section-label"><div><h2>See how the literature connects.</h2><p>Only references you record appear as lines. No connections are inferred.</p></div></div>${ps.length?`<div class="map-toolbar"><button class="button secondary" data-map-zoom="in" aria-label="Zoom in">+</button><button class="button secondary" data-map-zoom="out" aria-label="Zoom out">−</button><button class="button secondary" data-map-zoom="reset">Reset view</button><span>${ps.length} visible papers · ${current.edges.length} recorded references</span></div><div class="research-map" tabindex="0" aria-label="Literature map. Select a numbered paper below for details."><svg viewBox="0 0 800 520" role="img" aria-label="Recorded citation relationships"><defs><radialGradient id="map-bg"><stop stop-color="#263b63"/><stop offset="1" stop-color="#0c1526"/></radialGradient></defs><rect width="800" height="520" fill="url(#map-bg)"/><g id="map-world">${current.edges.map(edge=>{const a=pos.get(edge.from),b=pos.get(edge.to);return a&&b?`<path d="M${a.x} ${a.y} Q400 260 ${b.x} ${b.y}" fill="none" stroke="#899cda" stroke-width="1.5"/>`:''}).join('')}${ps.map((p,i)=>{const a=pos.get(p.id);return `<g data-node="${e(p.id)}"><circle cx="${a.x}" cy="${a.y}" r="28" fill="#65dbff0c" stroke="#65dbff40"/><circle cx="${a.x}" cy="${a.y}" r="15" fill="${['#65dbff','#ae9bff','#ffab91'][i%3]}"/><text x="${a.x}" y="${a.y+5}" text-anchor="middle" fill="#101929" font-size="13">${i+1}</text></g>`}).join('')}</g></svg></div><div id="map-detail" class="map-detail" hidden></div><div class="map-paper-list">${ps.map((p,i)=>`<details><summary><span>${i+1}</span>${e(p.title)}</summary><p>${e(p.authors)} · ${e(p.year||'Year unavailable')}</p><p>${e(p.abstract||'No abstract recorded.')}</p></details>`).join('')}</div>${ps.length>1?`<details class="research-add"><summary>Record a verified reference <span>+</span></summary><form id="edge-add" class="research-form"><p>Use this only after checking the citing paper’s reference list.</p><label>Citing paper<select name="from">${options()}</select></label><label>References this paper<select name="to">${options()}</select></label><button class="button primary">Add reference connection</button></form></details>`:''}`:'<div class="research-empty"><span class="empty-orbit">◎</span><h3>A map starts with your sources.</h3><p>Add papers to your library, then record verified references between them.</p></div>'}`}
 function proposal(){return `<div class="research-section-label"><div><h2>Make your thinking coherent.</h2><p>Write your argument. Add evidence from the Evidence tab with its source attached.</p></div></div><div class="proposal-editor"><label for="project-proposal">Your working proposal</label><textarea id="project-proposal" rows="20" maxlength="200000" placeholder="Start with your research problem, then develop your question and supporting evidence…">${e(current.proposal||'')}</textarea><div class="proposal-status"><span id="proposal-count">${(current.proposal||'').trim().split(/\s+/).filter(Boolean).length} words</span><span>Saved locally as you write</span></div></div><div class="actions"><button class="button primary" data-research-export="md">Export proposal</button><button class="button secondary" data-import-learning>Copy saved lesson drafts</button><a href="#notebook/readiness" class="text-link">Open readiness review ↗</a></div>`}
 function progress(){const done=[current.papers.length>0,current.evidence.length>0,current.proposal.trim().length>0,current.workbench?.design?.length>0].filter(Boolean).length;return done+'/4 foundations recorded'}
 function draftKey(){return current?'rei-research-form-'+current.id+'-'+active:null}
 function saveFormDraft(){const key=draftKey(),form=document.querySelector('.research-content form[data-wb-form],.research-content form[id]');if(!key||!form)return;const data=Object.fromEntries(new FormData(form));if(Object.values(data).some(v=>String(v).trim())){sessionStorage.setItem(key,JSON.stringify(data));const status=document.querySelector('#research-status');if(status)status.textContent='Draft saved locally'}else sessionStorage.removeItem(key)}
 function restoreFormDraft(){const key=draftKey(),form=document.querySelector('.research-content form[data-wb-form],.research-content form[id]');if(!key||!form)return;try{const data=JSON.parse(sessionStorage.getItem(key)||'null');if(!data)return;for(const el of form.elements)if(el.name&&typeof data[el.name]==='string'&&!el.value)el.value=data[el.name];form.closest('details')?.setAttribute('open','');const note=document.createElement('p');note.className='wb-hint';note.textContent='Draft restored on this device. Save it when ready.';form.prepend(note)}catch{sessionStorage.removeItem(key)}}
 function clearFormDraft(){const key=draftKey();if(key)sessionStorage.removeItem(key)}
 function render(){mapView={z:1,x:0,y:0};const host=document.querySelector('.research-shell');if(!host)return;if(!current){host.innerHTML=projectList();window.REIWorkbench?.afterRender();return}window.REIWorkbench?.normalize(current);host.innerHTML=`<div class="research-project-heading">${badge}<h1>${e(current.title)}</h1><p>${e(current.question)}</p><p class="research-progress" aria-label="Research progress">${progress()}</p><div class="research-project-actions"><span id="research-status" role="status">Saved on this device</span><button class="button secondary" data-research-export="json">Export project backup</button><span class="wb-hint">Includes notes and drafts. Use Review &amp; history for a backup with PDFs.</span></div></div><details class="research-add project-edit"><summary>Edit project details <span>+</span></summary><form id="project-edit" class="research-form">${field('Project title','title',current.title,'text',true)}${area('Working research question','question',current.question,3)}<div class="actions"><button class="button primary">Save project details</button><button type="button" class="text-button" data-delete-project>Delete project</button></div></form></details>${nav()}<section class="research-content">${({library,map,evidence,proposal})[active]?({library,map,evidence,proposal})[active]():window.REIWorkbench.render(active)}${active==='library'?window.REIWorkbench.libraryTools():active==='proposal'?window.REIWorkbench.proposalTools():''}</section>`;window.REIWorkbench?.afterRender()}
 async function mount(parts){const ticket=++epoch;try{projects=await store('readonly',s=>s.getAll());if(ticket!==epoch||location.hash.split('/')[0]!=='#research')return;current=projects.find(p=>p.id===parts[1])||null;active=tabs.includes(parts[2])?parts[2]:'library';render();restoreFormDraft()}catch{const h=document.querySelector('.research-shell');if(h)h.innerHTML='<div class="research-empty"><h1>Local storage is unavailable.</h1><p>Enable browser storage and reload to use research projects. Your existing learning workspace is separate.</p></div>'}}
 function validate(raw){if(raw?.version!==1||!raw.project||typeof raw.project.title!=='string')throw Error();const p=raw.project;if(!Array.isArray(p.papers)||!Array.isArray(p.evidence)||!Array.isArray(p.edges)||p.papers.length>200)throw Error();const ids=new Set();for(const paper of p.papers){if(typeof paper.id!=='string'||ids.has(paper.id)||typeof paper.title!=='string')throw Error();ids.add(paper.id);for(const k of ['authors','year','doi','url','venue','collection','abstract','status'])if(typeof paper[k]!=='string')throw Error()}for(const n of p.evidence){if(typeof n.id!=='string'||!ids.has(n.paperId))throw Error();for(const k of ['purpose','method','context','findings','limitations','relevance','locator'])if(typeof n[k]!=='string')throw Error()}for(const edge of p.edges)if(!ids.has(edge.from)||!ids.has(edge.to)||edge.from===edge.to)throw Error();if(typeof p.proposal!=='string'||typeof p.question!=='string')throw Error();window.REIWorkbench.validate(p);return {...p,id:id(),title:p.title+' (restored)',updated:new Date().toISOString()}}
 addEventListener('hashchange',saveFormDraft);
 document.addEventListener('input',ev=>{if(ev.target.closest('.research-content form'))saveFormDraft()});
 document.addEventListener('submit',async ev=>{const f=ev.target;if(!['project-edit','project-create','paper-add','evidence-add','edge-add'].includes(f.id))return;ev.preventDefault();const data=Object.fromEntries(new FormData(f));try{if(f.id==='project-edit'){if(current.question!==data.question.trim()){window.REIWorkbench.history(current,'Before question change');window.REIWorkbench.normalize(current).impact=true}current.title=data.title.trim();current.question=data.question.trim();await persist();render();return}if(f.id==='project-create'){if(projects.length>=5)return;if(!data.title.trim())return;current={id:id(),title:data.title.trim(),question:data.question.trim()||projectTemplates[data.template||'blank'].question,papers:[],evidence:[],edges:[],proposal:'',template:data.template||'blank',updated:new Date().toISOString()};const starter=projectTemplates[data.template||'blank'];if(starter.design)current.workbench={version:1,design:[{id:id(),...starter.design}]};await persist();location.hash='research/'+current.id+'/library';return}if(!current)return;if(f.id==='paper-add'){if(current.papers.length>=200&&!f.dataset.edit){toast('This project has reached its 200-paper limit.');return}data.title=data.title.trim();data.doi=doi(data.doi);if(!data.title)return;if(current.papers.some(p=>p.id!==f.dataset.edit&&((data.doi&&p.doi===data.doi)||p.title.toLowerCase()===data.title.toLowerCase()))){toast('This paper is already in your library.');return}if(data.year&&(Number(data.year)<1000||Number(data.year)>new Date().getFullYear()+1)){toast('Enter a valid publication year.');return}if(f.dataset.edit){const old=current.papers.find(p=>p.id===f.dataset.edit);Object.assign(old,data,{collection:data.collection.trim()||'Reading list'})}else current.papers.push({...data,id:id(),status:'To read',notes:'',collection:data.collection.trim()||'Reading list'})}if(f.id==='evidence-add'){if(!data.findings.trim()&&!data.relevance.trim()){toast('Add findings or relevance before saving your evidence.');return}if(f.dataset.edit)Object.assign(current.evidence.find(n=>n.id===f.dataset.edit),data);else current.evidence.push({...data,id:id()})}if(f.id==='edge-add'){if(data.from===data.to){toast('Choose two different papers.');return}if(current.edges.some(x=>x.from===data.from&&x.to===data.to)){toast('This reference is already recorded.');return}current.edges.push({...data,provenance:'User-verified reference'})}clearFormDraft();await persist();render()}catch{statusError()}});
 document.addEventListener('input',ev=>{if(ev.target.id==='paper-filter'){let found=0;document.querySelectorAll('.paper-record').forEach(p=>{p.hidden=!p.dataset.search.includes(ev.target.value.toLowerCase());if(!p.hidden)found++});document.querySelector('#paper-no-results').hidden=found>0}if(ev.target.dataset.paperNote&&current){const p=current.papers.find(p=>p.id===ev.target.dataset.paperNote);if(p){p.notes=ev.target.value;persist().catch(statusError)}}if(ev.target.id==='project-proposal'&&current){current.proposal=ev.target.value;document.querySelector('#proposal-count').textContent=current.proposal.trim().split(/\s+/).filter(Boolean).length+' words';persist().catch(statusError)}});
 document.addEventListener('change',async ev=>{if(ev.target.dataset.reading&&current){const p=current.papers.find(p=>p.id===ev.target.dataset.reading);if(p){p.status=ev.target.value;try{await persist()}catch{statusError()}}}if(ev.target.id==='research-restore'){try{const f=ev.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error();if(projects.length>=5){toast('The five-project limit has been reached.');return}const raw=JSON.parse(await f.text()),rp=raw.project||{},rw=rp.workbench||{};const pdfs=Array.isArray(rw.attachments)?rw.attachments.length:0;if(!confirm('Restore '+(rp.title||'untitled project')+'?\\n\\n'+(rp.papers?.length||0)+' papers · '+(rp.evidence?.length||0)+' evidence notes · '+(rw.claims?.length||0)+' claims\\nProposal: '+((rp.proposal||'').length)+' characters\\nPDF attachments: '+pdfs+'\\n\\nThis creates a separate project and does not overwrite existing work.'))return;const p=validate(raw);try{await window.REIWorkbench.restoreAttachments(p);await store('readwrite',s=>s.put(p))}catch(error){await window.REIWorkbench.removeFiles(p.id).catch(()=>{});throw error}toast('Backup restored as a separate project.');location.hash='research/'+p.id+'/library'}catch{toast('Could not restore this file. Use a valid REI project backup under 100 MB.')}}});
 document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b||!current||!location.hash.startsWith('#research/'))return;try{if(b.hasAttribute('data-delete-project')){if(!confirm('Delete this local project and all its research records? Export a project backup first if you want to keep a copy.'))return;await window.REIWorkbench.removeFiles(current.id);await store('readwrite',s=>s.delete(current.id));current=null;location.hash='research';return}if(b.dataset.researchExport){const type=b.dataset.researchExport;if(type==='json')await window.REIWorkbench.backup(current);if(type==='md')file('rei-proposal.md','# '+current.title+'\n\n'+current.proposal,'text/markdown');if(type==='csv'){const keys=['paper','quote','purpose','method','context','findings','limitations','relevance','locator'];const cell=s=>'"'+String(s??'').replace(/^[=+@-]/,' $&').replace(/"/g,'""')+'"';file('rei-evidence.csv',[keys.map(cell).join(','),...current.evidence.map(n=>keys.map(k=>cell(k==='paper'?current.papers.find(p=>p.id===n.paperId)?.title:n[k])).join(','))].join('\r\n'),'text/csv')}return}if(b.dataset.mapZoom){mapView.z=b.dataset.mapZoom==='reset'?1:Math.max(.5,Math.min(2.5,mapView.z+(b.dataset.mapZoom==='in'?.2:-.2)));if(b.dataset.mapZoom==='reset')mapView.x=mapView.y=0;updateMap();return}if(b.dataset.paperEdit||b.dataset.evidenceEdit){const paper=!!b.dataset.paperEdit,record=paper?current.papers.find(p=>p.id===b.dataset.paperEdit):current.evidence.find(n=>n.id===b.dataset.evidenceEdit);const form=document.querySelector(paper?'#paper-add':'#evidence-add');form.dataset.edit=record.id;for(const input of form.elements){if(input.name&&typeof record[input.name]==='string')input.value=record[input.name]}form.closest('details').open=true;form.querySelector('button').textContent='Save changes';form.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});form.querySelector('input,select').focus({preventScroll:true});return}if(b.dataset.paperRemove){if(current.evidence.some(n=>n.paperId===b.dataset.paperRemove)){toast('Remove this paper’s evidence notes first, so their source is not lost.');return}if(!confirm('Remove this paper and its map connections from this local project?'))return;await window.REIWorkbench.removeFiles(current.id,b.dataset.paperRemove);current.papers=current.papers.filter(p=>p.id!==b.dataset.paperRemove);current.edges=current.edges.filter(x=>x.from!==b.dataset.paperRemove&&x.to!==b.dataset.paperRemove)}else if(b.dataset.evidenceRemove){if(!window.REIWorkbench.canRemoveEvidence(b.dataset.evidenceRemove)){toast('Remove this evidence note from claims, comparisons, and synthesis coding before removing its source.');return}if(!confirm('Remove this evidence note? Text already copied to your proposal will remain.'))return;current.evidence=current.evidence.filter(n=>n.id!==b.dataset.evidenceRemove)}else if(b.dataset.insertEvidence){const n=current.evidence.find(n=>n.id===b.dataset.insertEvidence),p=current.papers.find(p=>p.id===n.paperId);current.proposal+='\n\n## '+p.title+'\n\n'+n.findings+'\n\n'+n.relevance+'\n\nSource: '+p.title+(p.doi?' — https://doi.org/'+p.doi:p.url?' — '+p.url:'')+(n.locator?' ('+n.locator+')':'');await persist();location.hash='research/'+current.id+'/proposal';return}else if(b.hasAttribute('data-import-learning')){if(!confirm('Append your saved lesson drafts to this proposal? Your original drafts stay unchanged.'))return;let old;try{old=JSON.parse(localStorage.getItem('rrh-v2')||'{}')}catch{toast('Could not read saved lessons.');return}const drafts=Object.entries(old.drafts||{}).filter(([k,v])=>/^\d$/.test(k)&&typeof v==='string'&&v.trim());if(!drafts.length){toast('No saved lesson drafts were found.');return}current.proposal+='\n\n'+drafts.map(([k,v])=>'## Lesson '+(Number(k)+1)+'\n\n'+v).join('\n\n')}else return;clearFormDraft();await persist();render()}catch{statusError()}});
 function updateMap(){document.querySelector('#map-world')?.setAttribute('transform',`translate(${400*(1-mapView.z)+mapView.x} ${260*(1-mapView.z)+mapView.y}) scale(${mapView.z})`)}
 let drag=null;
 document.addEventListener('pointerdown',ev=>{const map=ev.target.closest('.research-map');if(!map)return;const node=ev.target.closest('[data-node]');if(node){const paper=current?.papers.find(p=>p.id===node.dataset.node);if(paper){document.querySelectorAll('[data-node]').forEach(n=>n.dataset.selected=String(n===node));const detail=document.querySelector('#map-detail');detail.hidden=false;detail.innerHTML='<h3>'+e(paper.title)+'</h3><p>'+e(paper.authors)+' · '+e(paper.year||'Year unavailable')+'</p><p>'+e(paper.abstract||'No abstract recorded.')+'</p>'}return}drag={map,x:ev.clientX,y:ev.clientY};map.setPointerCapture(ev.pointerId)});
 document.addEventListener('pointermove',ev=>{if(!drag)return;const scale=800/drag.map.clientWidth;mapView.x+=(ev.clientX-drag.x)*scale;mapView.y+=(ev.clientY-drag.y)*scale;drag.x=ev.clientX;drag.y=ev.clientY;updateMap()});
 for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>drag=null);
 document.addEventListener('keydown',ev=>{if(!ev.target.matches('.research-map')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();mapView.x+=ev.key==='ArrowLeft'?20:ev.key==='ArrowRight'?-20:0;mapView.y+=ev.key==='ArrowUp'?20:ev.key==='ArrowDown'?-20:0;updateMap()});
 window.REIResearch={shell,mount};window.REIWorkbench.connect({get:()=>current,save:persist,render});
})();
